// The frontend under /public is hand-authored (converted from the design
// brief's .dc.html prototypes into real pages wired to the API) rather than
// generated by a template pass — the DC scaffolding (support.js, sc-if/sc-for,
// {{ }} bindings) doesn't have a mechanical 1:1 mapping to real fetch-backed
// markup. This script just verifies the build output is present and warns
// loudly if it's missing, so `npm run setup` fails fast instead of silently
// serving nothing.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const publicDir = path.join(ROOT, 'public');
const required = [
  'index.html', 'login.html', 'dashboard.html', 'classes.html', 'question-bank.html',
  'paper-maker.html', 'analytics.html', 'materials.html', 'credits.html', 'settings.html',
  'shared.js', 'styles.css'
];

const missing = required.filter((f) => !fs.existsSync(path.join(publicDir, f)));
if (missing.length) {
  console.error('Missing frontend files in /public:', missing.join(', '));
  process.exit(1);
}
console.log(`Frontend OK — ${required.length} files present in ${publicDir}`);
